import React from "react";

export default function ThemeToggle({
  theme,
  setTheme
}) {
  function toggleTheme() {
    setTheme(
      theme === "light" ? "dark" : "light"
    );
  }

  return (
    <button
      type="button"
      className="theme-toggle"
      onClick={toggleTheme}
      aria-label={
        theme === "light"
          ? "Switch to dark mode"
          : "Switch to light mode"
      }
      title={
        theme === "light"
          ? "Dark mode"
          : "Light mode"
      }
    >
      {theme === "light" ? "🌙" : "☀️"}
    </button>
  );
}
